import{c as n,Q as t,j as s,m as e}from"./chunks/framework.DOi4mjdC.js";const l="/assets/CPU%E4%BE%A7%E8%BF%90%E8%A1%8C%E9%AA%8C%E8%AF%81%E6%AD%A5%E9%AA%A4.B269LQ3y.png",h=JSON.parse('{"title":"ICPU_RUN_KF","description":"","frontmatter":{},"headers":[{"level":1,"title":"ICPU\\\\_RUN\\\\_KF","slug":"icpu_run_kf"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/调试接口/CPU孪生调试/ICPU_RUN_KF.md","filePath":"api/SIMD-API/基础API/调试接口/CPU孪生调试/ICPU_RUN_KF.md"}'),p={name:"api/SIMD-API/基础API/调试接口/CPU孪生调试/ICPU_RUN_KF.md"};function i(d,a,o,r,c,u){return t(),s("div",null,[...a[0]||(a[0]=[e(`<h1 id="icpu-run-kf" tabindex="-1">ICPU_RUN_KF <a class="header-anchor" href="#icpu-run-kf" aria-label="Permalink to &quot;ICPU\\_RUN\\_KF&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>√</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>√</td></tr><tr><td>Kirin X90</td><td>√</td></tr><tr><td>Kirin 9030</td><td>√</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>进行核函数的CPU侧运行验证时，CPU调测总入口，完成CPU侧的算子程序调用。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define ICPU_RUN_KF(func, blkdim, ...)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>func</td><td>输入</td><td>算子的kernel函数指针。</td></tr><tr><td>blkdim</td><td>输入</td><td>算子的核心数，corenum。</td></tr><tr><td>...</td><td>输入</td><td>所有的入参和出参，依次填入，当前参数个数限制为32个，超出32时会出现编译错误。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>除了func、blkdim以外，其他的变量都必须是通过GmAlloc分配的共享内存的指针；传入的参数的数量和顺序都必须和kernel保持一致。</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>下面代码以add_custom算子为例，介绍算子核函数在CPU侧验证时，算子调用的应用程序如何编写。您在实现自己的应用程序时，需要关注由于算子核函数不同带来的修改，包括算子核函数名，入参出参的不同等，合理安排相应的内存分配、内存拷贝和文件读写等，相关API的调用方式直接复用即可。</p><ol><li><p>按需包含头文件，通过ASCENDC_CPU_DEBUG宏区分CPU和NPU侧需要包含的头文件。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;data_utils.h&quot;</span></span>
<span class="line"><span>#ifndef ASCENDC_CPU_DEBUG</span></span>
<span class="line"><span>#include &quot;acl/acl.h&quot;</span></span>
<span class="line"><span>#else</span></span>
<span class="line"><span>#include &quot;tikicpulib.h&quot;</span></span>
<span class="line"><span>extern &quot;C&quot; __global__ __aicore__ void add_custom(GM_ADDR x, GM_ADDR y, GM_ADDR z); // 核函数声明</span></span>
<span class="line"><span>#endif</span></span></code></pre></div></li><li><p>CPU侧运行验证。完成算子核函数CPU侧运行验证的步骤如下：</p><p><strong>图 1</strong> CPU侧运行验证步骤<br><img src="`+l+`" alt="" title="CPU侧运行验证步骤"></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int32_t main(int32_t argc, char* argv[])</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    uint32_t numBlocks = 8;</span></span>
<span class="line"><span>    size_t inputByteSize = 8 * 2048 * sizeof(uint16_t);</span></span>
<span class="line"><span>    size_t outputByteSize = 8 * 2048 * sizeof(uint16_t);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   // 使用GmAlloc分配共享内存，并进行数据初始化</span></span>
<span class="line"><span>    uint8_t* x = (uint8_t*)AscendC::GmAlloc(inputByteSize);</span></span>
<span class="line"><span>    uint8_t* y = (uint8_t*)AscendC::GmAlloc(inputByteSize);</span></span>
<span class="line"><span>    uint8_t* z = (uint8_t*)AscendC::GmAlloc(outputByteSize);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    ReadFile(&quot;./input/input_x.bin&quot;, inputByteSize, x, inputByteSize);</span></span>
<span class="line"><span>    ReadFile(&quot;./input/input_y.bin&quot;, inputByteSize, y, inputByteSize);</span></span>
<span class="line"><span>    // 矢量算子需要设置内核模式为AIV模式</span></span>
<span class="line"><span>    AscendC::SetKernelMode(KernelMode::AIV_MODE);</span></span>
<span class="line"><span>    // 调用ICPU_RUN_KF调测宏，完成核函数CPU侧的调用</span></span>
<span class="line"><span>    ICPU_RUN_KF(add_custom, numBlocks, x, y, z);</span></span>
<span class="line"><span>    // 输出数据写出</span></span>
<span class="line"><span>    WriteFile(&quot;./output/output_z.bin&quot;, z, outputByteSize);</span></span>
<span class="line"><span>    // 调用GmFree释放申请的资源</span></span>
<span class="line"><span>    AscendC::GmFree((void *)x);</span></span>
<span class="line"><span>    AscendC::GmFree((void *)y);</span></span>
<span class="line"><span>    AscendC::GmFree((void *)z);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div></li></ol>`,16)])])}const A=n(p,[["render",i]]);export{h as __pageData,A as default};
